import{_ as t,o as d,c as o,a3 as a}from"./chunks/framework.cNy3aYYk.js";const v=JSON.parse('{"title":"Tenant Live Chat API","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant Live Chat API | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-live-chat"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant Live Chat API | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-live-chat"}]]},"headers":[],"relativePath":"api/tenant-v1-live-chat.md","filePath":"api/tenant-v1-live-chat.md","lastUpdated":1790349462000}'),c={name:"api/tenant-v1-live-chat.md"};function i(n,e,r,s,l,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="tenant-live-chat-api" tabindex="-1">Tenant Live Chat API <a class="header-anchor" href="#tenant-live-chat-api" aria-label="Permalink to &quot;Tenant Live Chat API&quot;">​</a></h1><p>Module: <code>live-chat</code> <strong>1.5.1</strong> · Base: <code>/api/tenant/v1/live-chat</code> (authenticated) and <code>/api/public/live-chat/{publicKey}</code> (widget).</p><h2 id="public-widget" tabindex="-1">Public widget <a class="header-anchor" href="#public-widget" aria-label="Permalink to &quot;Public widget&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/public/live-chat/{publicKey}/bootstrap</code></td><td>Greeting, branding, suggested_replies, agent_display_name, show_powered_by, offline, within_hours, accepting_live, optional realtime</td></tr><tr><td>POST</td><td><code>/api/public/live-chat/{publicKey}/sessions</code></td><td>Returns <code>session_token</code> once (max body 64KB; throttle <code>live-chat-widget-session</code>); banned visitors 403; seeds presence</td></tr><tr><td>POST</td><td><code>/api/public/live-chat/{publicKey}/heartbeat</code></td><td>Bearer session; updates last_seen_at / page / referrer / UA fields; returns <code>open_conversation_uuid</code> when an open thread exists (embed resume)</td></tr><tr><td>POST</td><td><code>/api/public/live-chat/{publicKey}/conversations</code></td><td>Bearer session; open/create — may be offline thread</td></tr><tr><td>GET</td><td><code>/api/public/live-chat/{publicKey}/conversations/{uuid}/messages</code></td><td>Poll with <code>since_id</code> (excludes <code>direction=note</code>)</td></tr><tr><td>POST</td><td><code>/api/public/live-chat/{publicKey}/conversations/{uuid}/messages</code></td><td>Visitor text or multipart attachment; offline leave-a-message when outside hours. Persist succeeds even if Reverb/notify fail (soft-fail).</td></tr><tr><td>POST</td><td><code>/api/public/live-chat/{publicKey}/conversations/{uuid}/typing</code></td><td>Bearer session; fans out <code>LiveChatTyping</code> (<code>direction=visitor</code>)</td></tr></tbody></table><p>Inactive widget → 404. Missing entitlement → 403. Bad/expired/revoked token → 401. CORS: Origin reflected for credential-less embeds.</p><p>The public embed (<code>public/widgets/live-chat.js</code>) stores the session token in <code>localStorage</code> and resumes via heartbeat + message hydrate after page refresh. Send failures show an in-panel error with <strong>Retry</strong> (no browser <code>alert</code>).</p><h2 id="tenant-agent" tabindex="-1">Tenant agent <a class="header-anchor" href="#tenant-agent" aria-label="Permalink to &quot;Tenant agent&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Permission</th></tr></thead><tbody><tr><td>GET</td><td><code>/live-chat/widget</code></td><td><code>view</code> or <code>manage</code></td></tr><tr><td>PATCH</td><td><code>/live-chat/widget</code></td><td><code>manage</code> (includes suggested_replies, show_powered_by, agent_display_name)</td></tr><tr><td>POST</td><td><code>/live-chat/widget/regenerate-key</code></td><td><code>manage</code></td></tr><tr><td>GET/POST/PATCH/DELETE</td><td><code>/live-chat/canned-replies</code></td><td><code>view</code> list; <code>manage</code> write</td></tr><tr><td>GET/POST/PATCH/DELETE</td><td><code>/live-chat/departments</code></td><td><code>view</code> list; <code>manage</code> write</td></tr><tr><td>GET</td><td><code>/live-chat/visitors/live</code></td><td><code>view</code> (<code>within</code> minutes, default 10)</td></tr><tr><td>GET</td><td><code>/live-chat/stats</code></td><td><code>view</code></td></tr><tr><td>POST</td><td><code>/live-chat/visitors/{id}/open-chat</code></td><td><code>reply</code></td></tr><tr><td>POST</td><td><code>/live-chat/visitors/{id}/ban</code> · <code>/unban</code></td><td><code>manage</code></td></tr><tr><td>GET</td><td><code>/live-chat/conversations</code></td><td><code>view</code> (filters: status, unread, my, assigned_to, department_id, is_offline, search)</td></tr><tr><td>GET</td><td><code>/live-chat/conversations/{id}</code></td><td><code>view</code></td></tr><tr><td>GET</td><td><code>/live-chat/conversations/{id}/messages</code></td><td><code>view</code> (includes notes)</td></tr><tr><td>POST</td><td><code>/live-chat/conversations/{id}/read</code></td><td><code>view</code></td></tr><tr><td>POST</td><td><code>/live-chat/conversations/{id}/messages</code></td><td><code>reply</code> (optional attachment; <code>as_note</code> boolean; soft-fail realtime)</td></tr><tr><td>POST</td><td><code>/live-chat/conversations/{id}/typing</code></td><td><code>reply</code> (<code>LiveChatTyping</code> <code>direction=agent</code> for embed)</td></tr><tr><td>POST</td><td><code>/live-chat/conversations/{id}/escalate</code></td><td><code>reply</code> (+ Help Desk entitled)</td></tr><tr><td>PATCH</td><td><code>/live-chat/conversations/{id}</code></td><td>Policy: <code>assigned_to</code>, <code>status</code>, <code>lead_id</code>, <code>department_id</code></td></tr></tbody></table><p><code>{id}</code> accepts numeric id or conversation uuid.</p><h2 id="realtime-channels" tabindex="-1">Realtime channels <a class="header-anchor" href="#realtime-channels" aria-label="Permalink to &quot;Realtime channels&quot;">​</a></h2><ul><li><code>private-tenant.{tenantId}.live-chat.inbox</code></li><li><code>private-tenant.{tenantId}.live-chat.conversation.{uuid}</code></li><li>Public <code>live-chat.visitor.{uuid}</code> for embed</li></ul><p>Events: <code>LiveChatMessageSent</code>, <code>LiveChatConversationUpdated</code>, <code>LiveChatVisitorPresence</code>, <code>LiveChatTyping</code>.</p>',12)])])}const u=t(c,[["render",i]]);export{v as __pageData,u as default};
